class Solution {
    public int[] closestNode(int n, int[][] edges, int[][] query) {
        List<Integer>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            g[e[0]].add(e[1]);
            g[e[1]].add(e[0]);
        }
        int[][] d = new int[n][n];
        for (int s = 0; s < n; s++) {
            Arrays.fill(d[s], -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            d[s][s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : g[u]) if (d[s][v] < 0) { d[s][v] = d[s][u] + 1; q.add(v); }
            }
        }
        int[] ans = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int s = query[i][0], e = query[i][1], x = query[i][2], best = -1;
            for (int u = 0; u < n; u++) {
                if (d[s][u] + d[u][e] != d[s][e]) continue;
                if (best < 0 || d[x][u] < d[x][best]) best = u;
            }
            ans[i] = best;
        }
        return ans;
    }
}
